  (3, 72,  'sdr',    'MQL'),
  (4, 72,  'ambos',  'SQL'),
  (5, 24,  'sdr',    'No-show'),
  (6, 24,  'closer', 'SE'),
  (7, 24,  'closer', 'OPP'),
